const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty = v => JSON.stringify(v ?? null, null, 2);
const num = (v, digits = 3) => v == null || v === '' ? '—' : Number.isFinite(Number(v)) ? Number(v).toLocaleString('zh-CN', {maximumFractionDigits: digits}) : esc(v);
const when = v => !v ? '—' : Number.isNaN(Date.parse(v)) ? esc(v) : esc(new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}));
const enc = encodeURIComponent;
const labels = {candidate:'候选',available:'可用',disabled:'停用',draft:'草稿',queued:'排队中',running:'运行中',completed:'已完成',succeeded:'成功',failed:'失败',paused:'已暂停',stopped:'已停止',interrupted:'中断',pause_requested:'等待检查点暂停',stop_requested:'等待检查点停止',research:'研究',selection:'选股',test:'最终测试',comparison:'多种子对照',data_import:'数据导入',final_test:'最终测试',preparing:'准备快照',selecting:'选择并冻结',finished:'已完成',ready:'就绪'};
const badge = v => `<span class="pill ${['available','succeeded','completed','finished','ready'].includes(v)?'green':['running','queued'].includes(v)?'blue':['failed','disabled','interrupted'].includes(v)?'red':''}">${esc(labels[v] || v || '未运行')}</span>`;
const btn = (text, action, data = '', cls = '', disabled = false) => `<button type="button" class="${cls}" data-action="${action}" ${data} ${disabled?'disabled':''}>${text}</button>`;
const empty = (title, message = '') => `<div class="empty"><div class="empty-icon">◇</div><strong>${esc(title)}</strong><p>${esc(message)}</p></div>`;
const json = (title, value, open = false) => `<details ${open?'open':''}><summary>${esc(title)}</summary><pre>${esc(pretty(value))}</pre></details>`;
const notice = (message, cls = '') => `<div class="notice ${cls}">${esc(message)}</div>`;
const metric = (label, value) => `<div class="metric"><div class="label">${esc(label)}</div><div class="value">${esc(value ?? '—')}</div></div>`;
const table = (heads, rows) => `<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const td = cells => `<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
const option = (value, label, selected) => `<option value="${esc(value)}" ${value === selected?'selected':''}>${esc(label)}</option>`;
function researchMethod(p={}){
 if(p.generator==='fixed')return {label:'固定因子基准',description:'不生成新公式，用已有因子组合建立比较基准。'};
 if(p.generator==='random')return {label:'随机搜索新因子',description:'随机提出公式，检查它们是否能改善现有组合。'};
 const rewards={single_ic:['PPO · 单因子预测反馈','根据单个因子与后续收益的排序相关性训练公式生成器。'],trade_delta:['PPO · 组合交易增量反馈','根据新因子给组合交易表现带来的净增量训练公式生成器。'],combo_ic:['PPO · 组合预测反馈','根据组合与后续收益的排序相关性训练公式生成器。'],absolute_trade:['PPO · 绝对交易表现反馈','根据组合的绝对交易评价训练公式生成器。']};
 if(p.generator==='ppo'&&rewards[p.reward_mode])return {label:rewards[p.reward_mode][0],description:rewards[p.reward_mode][1]};
 return {label:p.generator||'尚未配置研究方法',description:`奖励方式：${p.reward_mode||'尚未配置'}`};
}
function experimentTitle(e){return /^raw500-v1-mechanism(?:\s|[·—-])/.test(e.name||'')?`500股机制验收 · ${researchMethod(e.protocol).label} · 种子 ${e.protocol?.seed}`:(e.name||'未命名实验');}
function initialPool(p={}){return Object.fromEntries((p.initial_expressions||[]).map((x,i)=>[x,p.initial_weights?.[i]??0]));}
function poolEntries(weights={}){return Object.entries(weights).filter(([,w])=>Number.isFinite(Number(w)));}
function activePool(weights={}){return Object.fromEntries(poolEntries(weights).filter(([,w])=>Number(w)!==0));}
function poolKey(weights={},withWeights=true){return JSON.stringify(Object.entries(activePool(weights)).sort(([a],[b])=>a.localeCompare(b)).map(([x,w])=>withWeights?[x,Number(w)]:x));}
function poolChange(a,b){return poolKey(a)===poolKey(b)?'因子与权重均相同':poolKey(a,false)===poolKey(b,false)?'因子相同，权重已变化':'因子组成已变化';}
function frozenCombination(e){
 const m=S.models.find(m=>m.version_id===e.model_version);
 if(m?.weights)return {weights:m.weights,batch:m.source?.selected_batch,source:'已登记冻结模型'};
 if(e.selection?.rule!=='max_V_J_earliest_tie_no_refit'||!e.selection?.frozen_model_id)return null;
 const checkpoints=(e.selection.checkpoints||[]).filter(c=>c.weights&&Number.isFinite(c.objective));
 const selected=checkpoints.reduce((best,c)=>!best||c.objective>best.objective||(c.objective===best.objective&&c.batch_id<best.batch_id)?c:best,null);
 return selected?{weights:selected.weights,batch:selected.batch_id,source:'按已记录的 V 选择规则还原'}:null;
}
function factorMeaning(expression){
 const direct={open:'开盘价',close:'收盘价',high:'最高价',low:'最低价',volume:'成交量',amount:'成交额',intraday_return:'日内涨跌幅',overnight_gap:'隔夜跳空幅度',range_relative:'相对振幅',close_location:'收盘价在当日区间的位置'};
 if(direct[expression])return direct[expression];
 const neg=expression.match(/^neg\((.*)\)$/);if(neg)return `取反：${factorMeaning(neg[1])}`;
 const match=expression.match(/^(return|volatility|volume_ratio|ma_gap)_(\d+)$/);
 if(match)return `${match[2]}日${{return:'收益率',volatility:'波动率',volume_ratio:'成交量相对均值',ma_gap:'价格均线偏离'}[match[1]]}`;
 return '生成的复合公式；精确定义见右侧原始表达式';
}
function factorWeightsTable(weights){const entries=poolEntries(weights);return entries.length?table(['因子含义','原始表达式','组合权重','参与评分'],entries.map(([expression,w])=>td([esc(factorMeaning(expression)),`<code class="factor-expression">${esc(expression)}</code>`,`${num(Number(w)*100,4)}%`,Number(w)!==0?'是':'否 · 权重为零']))):empty('尚无组合记录');}
function experimentResultCell(e){const frozen=frozenCombination(e);if(!frozen)return '<span class="subtle">尚未冻结</span>';const peers=S.experiments.filter(x=>x.id!==e.id&&frozenCombination(x)&&poolKey(frozenCombination(x).weights)===poolKey(frozen.weights));return `<strong>${Object.keys(activePool(frozen.weights)).length} 个实际因子</strong><br><span class="subtle">与起点相比：${esc(poolChange(initialPool(e.protocol),frozen.weights))}${peers.length?`<br>与另外 ${peers.length} 个实验的因子及权重相同`:''}</span>`;}
const pages = {projects:['研究项目','▦'],models:['模型管理','◈'],data:['数据中心','▤'],selection:['选股工作台','▦'],plans:['我的方案','▣'],history:['选股记录','☷'],jobs:['任务状态','◷'],settings:['设置','⚙'],help:['方法帮助','?']};
const tabs = ['实验配置','运行与迭代','因子与组合','回测与选股','验证报告'];
const saved = (()=>{try{return JSON.parse(localStorage.getItem('factor-workspace') || '{}')}catch{return {}}})();
const S = {workspace:saved.workspace === 'selection'?'selection':'research', page:saved.page, projects:[],experiments:[],models:[],datasets:[],plans:[],results:[],jobs:[],comparisons:[],experiment:null,tab:0,project:null,result:null,selectionJob:null,config:{model_version:'',dataset_id:'',filters:{},top_n:50},plan:null,busy:false};
if (!pages[S.page]) S.page = S.workspace === 'research'?'projects':'selection';
try {const draft=JSON.parse(localStorage.getItem('factor-selection-draft')||'null');if(draft?.model_version)S.config=draft;} catch {}
let viewToken = 0, toastTimer, protocolDraft = null;

async function api(path, method = 'GET', body) {
  const response = await fetch(`/api${path}`, {method, headers:body===undefined?{}:{'Content-Type':'application/json'}, body:body===undefined?undefined:JSON.stringify(body)});
  const text = await response.text(); let result; try {result = text ? JSON.parse(text):null;} catch {result = text;}
  if (!response.ok) {const detail = result?.detail ?? result?.error ?? result;throw new Error(typeof detail === 'string'?detail:pretty(detail));}
  return result;
}
function toast(message) { const node=$('#toast');node.textContent=message;node.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.style.display='none',4200); }
function persist() {try{localStorage.setItem('factor-workspace',JSON.stringify({workspace:S.workspace,page:S.page}));localStorage.setItem('factor-selection-draft',JSON.stringify(S.config));}catch{}}
function shell() {
  const nav = S.workspace==='research'?['projects','models','data']:['selection','plans','history'];
  $('#app').innerHTML = `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">ƒ</span>因子研究与选股</div><select id="workspace" class="workspace" aria-label="切换工作区">${option('research','研究工作区',S.workspace)}${option('selection','选股工作区',S.workspace)}</select><div class="nav-caption">${S.workspace==='research'?'RESEARCH / 研究':'SELECTION / 选股'}</div><nav class="nav" aria-label="主要导航">${nav.map(p=>`<button data-action="navigate" data-page="${p}" class="${S.page===p?'active':''}"><span class="icon">${pages[p][1]}</span>${pages[p][0]}</button>`).join('')}</nav><div class="sidebar-bottom"><nav class="nav" aria-label="辅助导航">${['jobs','settings','help'].map(p=>`<button data-action="navigate" data-page="${p}" class="${S.page===p?'active':''}"><span class="icon">${pages[p][1]}</span>${pages[p][0]}</button>`).join('')}</nav><div class="sidebar-foot">本地研究平台 · v1.0</div></div></aside><div class="main-area"><header class="topbar"><div><div class="breadcrumbs">${S.workspace==='research'?'研究工作区':'选股工作区'} / ${pages[S.page][0]}</div><h1>${pages[S.page][0]}</h1></div><div class="top-actions"><span><i class="status-dot"></i>本地工作区</span>${btn('刷新','refresh','','link')}</div></header><main class="main" id="main" tabindex="-1"><div class="loading">正在读取实际记录…</div></main></div></div>`;
}
function dialog(title, content) { $('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2>${btn('×','close-dialog','','dialog-close')}</div><div class="dialog-body">${content}<div class="error-text" id="dialog-error" role="alert"></div></div>`;if(!$('#dialog').open)$('#dialog').showModal(); }
function closeDialog(){ $('#dialog').close(); }
async function navigate(page) {S.page=page;if(['projects','models','data'].includes(page))S.workspace='research';if(['selection','plans','history'].includes(page))S.workspace='selection';persist();shell();await loadPage();}
async function lists(names) {await Promise.all(names.map(async name=>{S[name]=await api(`/${name}`);}));}
async function loadPage() {
  const token=++viewToken;
  try {
    if(S.page==='projects') {await lists(['projects','experiments','datasets','comparisons','jobs','models']);if(S.experiment)S.experiment=await api(`/experiments/${enc(S.experiment.id)}`);}
    if(S.page==='models')await lists(['models','experiments','datasets']);
    if(S.page==='data')await lists(['datasets']);
    if(S.page==='selection') {await lists(['models','datasets','results']);if(!S.config.model_version){const m=S.models.find(m=>m.status==='available'&&m.is_default)||S.models.find(m=>m.status==='available');if(m)selectModel(m.version_id);}if(S.config.model_version)S.config.dataset_id=currentModel()?.dataset_id||'';persist();if(!S.result&&S.results.length)S.result=await api(`/results/${enc(S.results[0].id)}`);}
    if(S.page==='plans')await lists(['plans','models','datasets']);
    if(S.page==='history')await lists(['results']);
    if(S.page==='jobs')await lists(['jobs']);
    if(S.page==='settings')S.settings=await api('/settings');
    if(S.page==='help')S.help=await api('/help');
    if(token===viewToken)render();
  }catch(error){if(token===viewToken)$('#main').innerHTML=notice(`无法读取页面：${error.message}`,'error')+`<p>${btn('重试','refresh','','primary')}</p>`;}
}
function render(){const views={projects:projectView,models:modelView,data:dataView,selection:selectionView,plans:planView,history:historyView,jobs:jobsView,settings:settingsView,help:helpView};$('#main').innerHTML=views[S.page]();}
function projectView() {
 if(S.experiment)return experimentView();
 const project=S.projects.find(p=>p.id===S.project), experiments=S.experiments.filter(e=>!S.project||e.project_id===S.project);
 return `<div class="page-intro"><div><div class="eyebrow">RESEARCH PROJECTS</div><h2>从一个问题，开始研究</h2><div class="subtle">锁定数据与协议，追踪每一次候选、组合评价和策略更新。</div></div><div class="actions">${btn('新建项目','new-project')}${btn('＋ 新建实验','new-experiment','','primary',!S.projects.length||!S.datasets.length)}</div></div>${!S.datasets.length?notice('尚无数据快照。请先在数据中心导入并建立快照，再创建实验。','warning'):''}<div class="grid">${S.projects.map(p=>`<article class="card project-card"><div class="row between"><h3>${esc(p.name)}</h3><span class="pill">${S.experiments.filter(e=>e.project_id===p.id).length} 个实验</span></div><div class="question">${esc(p.question||'尚未填写研究问题')}</div><footer><span class="subtle">${when(p.created_at)}</span>${btn('查看实验 →','project-filter',`data-id="${esc(p.id)}"`,'link')}</footer></article>`).join('')||`<section class="card">${empty('建立第一个研究项目','项目集中保存研究问题、实验协议与对照证据。')}</section>`}</div><section class="card"><div class="card-head"><div><h3>${project?esc(project.name):'全部实验'}</h3><p class="subtle">不同方法与种子可能选出完全相同的组合；相同结果会明确标注。运行后参数锁定。</p></div><div class="actions">${project?btn('全部项目','project-filter','','link'):''}${btn('比较已选实验','compare-experiments','','link')}</div></div>${experiments.length?table(['比较','实验名称与方法','起点与研究规模','冻结结果','状态','操作'],experiments.map(e=>td([`<input type="checkbox" class="experiment-compare" value="${esc(e.id)}" aria-label="选择 ${esc(e.name)} 比较">`,`<strong class="experiment-name">${esc(experimentTitle(e))}</strong><div class="subtle">${esc(researchMethod(e.protocol).label)} · 种子 ${esc(e.protocol?.seed)}</div>${json("记录编号与原始名称",{id:e.id,name:e.name,protocol:e.protocol?.name,dataset:e.dataset_id,created_at:e.created_at})}`,`<div class="research-budget">起始 ${(e.protocol?.initial_expressions||[]).length} 个 · 容量 ${esc(e.protocol?.max_factors)} 个<br><span class="subtle">${e.protocol?.generator==='fixed'?'固定基准，不生成新候选':`${esc(e.protocol?.batches)} 批 × ${esc(e.protocol?.episodes_per_batch)} 次候选采样`}；每次组合搜索 ${esc(e.protocol?.search_budget)} 次</span></div>`,experimentResultCell(e),badge(e.status),btn('打开实验','open-experiment',`data-id="${esc(e.id)}"`,'link')]))):empty('尚无实验','创建实验时将从所选数据的实际日期生成完整协议模板。')}</section>${comparisonView()}`;
}
function comparisonView(){const rows=S.comparisons.filter(x=>!S.project||x.project_id===S.project),groupNames={A:'固定因子基准',B:'随机搜索新因子',C:'PPO · 单因子预测反馈',E:'PPO · 组合交易增量反馈'};return rows.length?`<section class="card"><div class="card-head"><h3>多次重复运行 · 方法对照</h3><span class="subtle">种子不同代表重复抽样；组别字母只作记录编号</span></div><div class="card-body">${rows.map(c=>`<div class="row between"><strong>${c.protocol?.initial_expressions?.length||'—'} 因子起点 · ${when(c.created_at)}</strong>${badge(c.result?'completed':S.jobs.find(j=>j.id===c.job_id)?.status||c.status||'queued')}</div><p class="subtle">验证期目标用于选择冻结模型；测试期目标用于冻结后的历史诊断。目标值不是收益率，须结合费用、风险和同口径对照解释。</p>${c.result?.summary?table(['研究方法','重复种子数','验证期目标均值','验证期标准差','质量失败率','实际回测均值','测试期目标均值'],Object.entries(c.result.summary).map(([g,m])=>td([`${esc(groupNames[g]||g)} <span class="subtle">(${esc(g)})</span>`,num(m.seeds,0),num(m.V_objective_mean,6),num(m.V_objective_std,6),num(m.failure_rate_mean*100,2)+'%',num(m.actual_backtests_mean,0),num(m.T_objective_mean,6)]))):notice('对照尚未完成，请在任务状态查看排队、运行或失败原因。')}${json('高级证据：对照配置、记录编号与真实报告',c)}`).join('')}</div></section>`:'';}
function experimentView(){const e=S.experiment;return `<div class="page-intro"><div><div class="row">${btn('← 项目','back-projects','','link')}</div><h2 style="margin-top:14px">${esc(experimentTitle(e))}</h2><div class="subtle">${esc(researchMethod(e.protocol).description)} · ${e.protocol?.synthetic?'合成数据':'实际历史数据'} · ${e.protocol?.data_mode==='legacy_prototype'?'历史数据原型口径':esc(e.protocol?.data_mode||'未声明数据模式')}</div>${json('原始名称、数据与记录编号',{name:e.name,id:e.id,protocol:e.protocol?.name,dataset:e.dataset_id})}</div><div class="row">${badge(e.status)}${btn('派生新实验','clone-experiment')}</div></div><div class="tabs" role="tablist">${tabs.map((t,i)=>`<button role="tab" aria-selected="${S.tab===i}" class="${S.tab===i?'active':''}" data-action="experiment-tab" data-tab="${i}">${t}</button>`).join('')}</div>${[experimentConfig,experimentRun,experimentFactors,experimentBacktest,experimentValidation][S.tab](e)}`;}
function experimentConfig(e){const p=e.protocol||{},method=researchMethod(p);return `<section class="card"><div class="card-head"><h3>本次实验怎么做</h3><span class="pill blue">${e.status==='draft'?'待启动 · 已保存草稿':'研究规则已锁定'}</span></div><div class="card-body"><div class="research-explainer"><strong>${esc(method.label)}</strong><p>${esc(method.description)}</p><p>“实验”是一次实际运行；“协议”是这次运行事先固定的规则，包括使用哪段历史、尝试多少次、如何评分和选模型。随机种子 ${esc(p.seed)} 用于复现抽样，不是模型好坏的分数。</p></div><div class="metric-row">${metric('初始因子数',p.initial_expressions?.length)}${metric('组合容量上限',p.max_factors)}${metric('每期目标持股数',p.top_k)}${metric('计划批次',p.batches)}${metric('每批候选采样',p.episodes_per_batch)}${metric('单次组合搜索预算',p.search_budget)}</div><p class="subtle">初始因子是人工指定的起点；容量上限不等于最终因子数。最终参与评分的数量见「因子与组合」。相同种子只有在相同数据、代码与规则下才具备复现意义。</p><div style="margin-top:22px">${segmentsTable(p)}</div><p class="subtle">F 负责搜索组合权重，E 负责给候选反馈，V 负责挑选并冻结已记录组合，T 只在冻结后检查最终表现。${p.holdout_status==='previously_observed_historical'?'当前 T 属于此前观察过的历史区间，应按历史诊断解释。':''}</p>${readableProtocolRules(p)}${json('高级原始证据 · 完整协议',p)}<p class="subtle">要修改规则请「派生新实验」；已有实验与证据保留。</p></div></section>`;}
function readableProtocolRules(p){return `<div class="research-chart-grid-layout"><div><h4>怎样模拟交易</h4>${table(['规则','本次设定'],[['初始资金',num(p.initial_cash,2)+' 元'],['买入费率',ResearchUI.pct(p.buy_fee)],['卖出费率',ResearchUI.pct(p.sell_fee)],['最低手续费',num(p.minimum_fee,2)+' 元 / 笔'],['滑点比例',ResearchUI.pct(p.slippage)],['每手股数',num(p.lot_size,0)],['目标持股',num(p.top_k,0)+' 只']].map(x=>td(x.map(esc))))}</div><div><h4>怎样奖励与停止</h4><p class="subtle">${esc(researchMethod(p).description)} 每轮尝试完毕后，按反馈期评价决定是否采用变化；验证期只选择已登记的检查点，不再重新拟合。</p>${table(['规则','本次设定'],[['最多回测调用',num(p.max_backtests,0)],['最长运行时间',p.wall_seconds==null?'未设墙钟上限':num(p.wall_seconds,0)+' 秒'],['参加验证的轮次',(p.selection_batches||[]).map(x=>'第'+x+'轮').join('、')||'未登记'],['风险惩罚系数',num(p.risk_lambda,4)],['复杂度惩罚系数',num(p.beta,4)],['奖励尺度',num(p.tau,4)]].map(x=>td(x.map(esc))))}<p class="subtle">费用和滑点已计入净收益。上限是预算，不是保证会发生这么多次新回测；缓存命中仍占逻辑预算。</p></div></div>`;}
function segmentsTable(p){return table(['分区','用途','开始','结束'],['F','E','V','T'].filter(s=>p?.segments?.[s]).map(s=>[s,p.segments[s]]).map(([s,v])=>td([esc(s),{F:'组合搜索',E:'增量奖励',V:'模型选择',T:'冻结后最终测试'}[s]||'—',esc(v[0]),esc(v[1])])));}
function researchContext(){return {S,esc,num,when,btn,table,td,json,notice,metric,empty,badge,option,initialPool,activePool,poolChange,frozenCombination,factorWeightsTable,R:ResearchUI};}
function experimentRun(e){return globalThis.ResearchProcess?ResearchProcess.run(e,researchContext()):empty('运行过程视图正在更新','请稍后刷新。');}
function artifactTable(items,keys){if(!items||!Object.keys(items).length)return empty('尚无运行产物','启动实验后，此处展示真实计算记录。');const rows=Array.isArray(items)?items:Object.values(items);const found=keys.filter(k=>rows.some(r=>r&&typeof r==='object'&&k in r));if(!found.length)return `<div class="card-body">${json('查看实际记录',items,true)}</div>`;const captions={batch_id:'批次',expression:'因子表达式',status:'状态',reward:'奖励',delta:'增量',error:'错误',pool_version:'池版本',pool:'因子池',weights:'权重',parameter_l2_change:'参数 L2 变化',episodes:'采样次数',negative_episodes:'负奖励次数',losses:'训练损失'};return table([...found.map(k=>captions[k]||k),'证据'],rows.map((r,i)=>td([...found.map(k=>`<span class="${k==='expression'?'mono':''}">${esc(typeof r[k]==='object'?JSON.stringify(r[k]):r[k]??'—')}</span>`),`<details><summary>记录 ${i+1}</summary><pre>${esc(pretty(r))}</pre></details>`])));}
function experimentFactors(e){
 const initial=initialPool(e.protocol),pools=Array.isArray(e.pools)?e.pools:[],frozen=frozenCombination(e),latest=e.run_status?.pool||pools.at(-1)?.weights;
 const stats=pool=>`${Object.keys(activePool(pool)).length} 个非零权重因子`;
 let previous=initial;
 const rows=pools.map(p=>{const w=p.weights||p.pool||{},change=poolChange(previous,w);previous=w;return td([`第 ${esc(p.batch_id)} 批`,esc(p.pool_version),stats(w),esc(change),p.registered_for_selection?'是':'否',`<details><summary>查看此批权重</summary>${factorWeightsTable(w)}${json('原始批次记录',p)}</details>`]);});
 return `<section class="card"><div class="card-head"><h3>本次组合到底有没有变化</h3></div><div class="card-body"><div class="metric-row">${metric('起始实际因子数',Object.keys(activePool(initial)).length)}${metric('最新实际因子数',latest?Object.keys(activePool(latest)).length:'未运行')}${metric('冻结实际因子数',frozen?Object.keys(activePool(frozen.weights)).length:'未冻结')}${metric('尝试候选公式',e.trials?.length||0)}</div><p>${frozen?`冻结结果相对起点：<strong>${esc(poolChange(initial,frozen.weights))}</strong>。`:latest?`最新池相对起点：${esc(poolChange(initial,latest))}；尚未完成模型冻结。`:'尚未开始运行。'}</p>${frozen?experimentResultCell(e):''}${notice('候选被尝试、PPO 参数被更新，都不等于新因子已进入组合，更不等于效果提高。下表展示实际采用的权重；非零权重因子数也不代表相互独立的信息来源。')}</div></section><section class="card"><div class="card-head"><h3>1. 初始因子池 · 研究起点</h3><span class="subtle">来自启动前协议，${stats(initial)}</span></div>${factorWeightsTable(initial)}</section><section class="card"><div class="card-head"><h3>2. 每批结束后实际采用的组合</h3><span class="subtle">每批最多提交一次变更；相同记录会明确标注</span></div>${rows.length?table(['批次','池版本','实际因子数','相对上一批 / 起点','参加 V 选择','组合明细'],rows):empty('尚无批次记录')}</section><section class="card"><div class="card-head"><h3>3. 冻结组合 · 最终参与选股的权重</h3>${e.model_version?btn('查看冻结模型','open-model',`data-id="${esc(e.model_version)}"`,'link'):''}</div>${frozen?`<div class="card-body"><p>来源：${esc(frozen.source)} · 第 ${esc(frozen.batch)} 批 · ${stats(frozen.weights)}。V 从预先登记的检查点中选择，冻结后不重新拟合。</p></div>${factorWeightsTable(frozen.weights)}`:empty('尚未冻结模型','先完成研究批次，再按预登记规则在 V 中选取组合。')}<div class="card-body">${e.selection?json('查看 V 选择原始证据',e.selection):''}</div></section>`;
}
function experimentBacktest(e){return ResearchBacktest.view(e,researchContext());}
function backtestEvidence(){return ResearchBacktest.evidence(S.experiment,researchContext());}
function backtestDay(){return ResearchBacktest.day(researchContext());}
let backtestRequest=0;
function renderBacktest(){if(S.page==='projects'&&S.experiment&&S.tab===3)render();}
async function selectBacktest(id){
 const experimentId=S.experiment?.id,token=++backtestRequest;
 S.backtestId=id;S.backtest=null;S.backtestLoading=!!id;S.backtestError=null;renderBacktest();
 if(!id)return;
 try{const value=await api(`/experiments/${enc(experimentId)}/backtests/${enc(id)}`);if(token!==backtestRequest||S.experiment?.id!==experimentId)return;S.backtest=value;S.backtestDate=null;}
 catch(error){if(token===backtestRequest&&S.experiment?.id===experimentId)S.backtestError=`这份结果读取失败：${error.message}`;}
 finally{if(token===backtestRequest&&S.experiment?.id===experimentId){S.backtestLoading=false;renderBacktest();}}
}
async function loadBacktests(requestedId=null){
 const experimentId=S.experiment?.id,token=++backtestRequest;
 S.backtestLoading=true;S.backtestError=null;renderBacktest();
 try{const records=await api(`/experiments/${enc(experimentId)}/backtests`);if(token!==backtestRequest||S.experiment?.id!==experimentId)return;S.backtests=records;
 const chosen=records.find(b=>b.artifact_id===(requestedId||S.backtestId))||ResearchBacktest.preferred(records);
 S.backtestGroup=S.backtestGroup||'outcomes';
 if(chosen&&!ResearchBacktest.filtered(records,S.backtestGroup).some(b=>b.artifact_id===chosen.artifact_id))S.backtestGroup=requestedId?'all':chosen.segment==='F'?'search':'candidates';
 await selectBacktest(chosen?.artifact_id||'');
 }catch(error){if(token===backtestRequest&&S.experiment?.id===experimentId){S.backtestLoading=false;S.backtestError=`无法载入已有结果：${error.message}`;renderBacktest();}}
}
function experimentValidation(e){return globalThis.ResearchProcess?ResearchProcess.validation(e,researchContext()):empty('验证报告视图正在更新','请稍后刷新。');}
function modelView(){return `<div class="page-intro"><div><div class="eyebrow">MODEL REGISTRY</div><h2>研究成果，明确版本</h2><div class="subtle">计算版本不可变。人工开放前台，与评价状态、数据就绪状态分别记录。</div></div><span class="pill">${S.models.length} 个版本</span></div><section class="card">${S.models.length?table(['模型 / 版本','使用状态','评价','当前数据','来源','操作'],S.models.map(m=>td([`<strong>${esc(m.name)}</strong><div class="subtle">${Object.keys(activePool(m.weights||{})).length} 个因子 · ${when(m.created_at)}</div>${json('高级版本编号',{model_version:m.version_id})}`,badge(m.status),esc(evaluationLabel(typeof m.evaluation==='string'?m.evaluation:m.evaluation?.status)),m.data_ready?'<span class="pill green">就绪</span>':`<span class="pill amber">未就绪</span><br><span class="subtle">${esc(m.blocked_reason||'查看数据要求')}</span>`,esc(S.experiments.find(e=>e.id===m.source_experiment_id)?.name||'已登记研究模型'),btn('查看 / 管理','open-model',`data-id="${esc(m.version_id)}"`,'link')]))):empty('尚无冻结模型','研究完成后自动登记候选版本。查看证据并人工设为可用，才会出现在选股工作台。')}</section>`;}
function dataView(){return `<div class="page-intro"><div><div class="eyebrow">DATA & QUALITY</div><h2>数据快照与字段质量</h2><div class="subtle">按用途记录字段权限、核验结果与原型假设；实际数据日期与系统日期分开显示。</div></div><div class="actions">${btn('导入说明','data-import')}${btn('导入 / 更新数据','run-data-import','','primary')}</div></div>${S.datasets.map(d=>`<section class="card"><div class="card-head"><div><h3>${esc(d.name||d.id)}</h3><p class="subtle mono">${esc(d.id)}</p></div><div class="row">${badge(d.status)}<span class="pill">${esc(d.data_mode)}</span>${btn('字段与质量','dataset-detail',`data-id="${esc(d.id)}"`,'link')}</div></div><div class="card-body"><div class="metric-row">${metric('证券数',num(d.code_count,0))}${metric('交易日',num(d.session_count,0))}${metric('数据行数',num(d.rows,0))}${metric('最新完整实际日',d.latest_complete_date||'未核验')}</div><p class="subtle">实际覆盖 ${esc(d.start||'—')} 至 ${esc(d.end||'—')}</p>${d.data_mode!=='audited'?notice('该快照仍为原型研究数据；完整历史修订和公司行动口径须按质量报告核验。','warning'):''}</div></section>`).join('')||`<section class="card">${empty('尚无数据快照','点击上方「导入 / 更新数据」启动流式导入，再在任务状态查看进度。')}</section>`}`;}
function currentModel(){return S.models.find(m=>m.version_id===S.config.model_version);}
function currentDataset(){return S.datasets.find(d=>d.id===(S.config.dataset_id||currentModel()?.dataset_id));}
function selectModel(id){S.config.model_version=id;const m=S.models.find(m=>m.version_id===id);S.config.dataset_id=m?.dataset_id||'';S.config.filters={};S.config.top_n=m?.top_k??m?.default_top_k??50;S.plan=null;persist();}
function displayUnit(unit){return String(unit).replace(/calendar days/gi,'自然日').replace(/percent/gi,'百分比 %').replace(/CNY/gi,'元').replace(/\(inferred\)/gi,'，单位待核验').replace(/inferred/gi,'推定，待核验');}
function filterControl(key,label){const f=currentDataset()?.filters?.[key],active=f?.enabled===true,unit=f?.unit?`（${displayUnit(f.unit)}）`:'',reason=!active&&key==='board'?'板块字典与历史变更待核验':!active&&key==='amount'?'金额单位待核验，暂不可筛选':f?.reason,v=S.config.filters[key]||{};if(key==='board'){const opts=f?.options||f?.values||[];return `<label>${label}${active&&opts.length?`<select id="filter-board" multiple size="2" aria-label="上市板块，可多选">${opts.map(x=>{const value=typeof x==='object'?x.value:x;return `<option value="${esc(value)}" ${(S.config.filters.board||[]).includes(value)?'selected':''}>${esc(typeof x==='object'?x.label:x)}</option>`}).join('')}</select>`:`<input disabled value="${active?'未提供可选板块':'未开放'}">`}<small>${esc(reason||(active?'留空表示全部，支持多选':'未通过字段核验'))}</small></label>`;}return `<label>${label}${esc(unit)}<span class="range"><input type="number" step="any" data-filter="${key}" data-bound="min" value="${esc(v.min??'')}" placeholder="最低" aria-label="${label}最低值" ${active?'':'disabled'}><span>—</span><input type="number" step="any" data-filter="${key}" data-bound="max" value="${esc(v.max??'')}" placeholder="最高" aria-label="${label}最高值" ${active?'':'disabled'}></span><small>${esc(active?'留空不限 · 包含边界':reason||'未通过字段核验')}</small></label>`;}
function selectionView(){const m=currentModel(),d=currentDataset(),available=S.models.filter(m=>m.status==='available'||m.version_id===S.config.model_version),ready=m?.status==='available'&&m.data_ready!==false&&!!d;const date=d?.latest_complete_date||m?.data_date,stale=date&&Math.floor((Date.now()-Date.parse(date))/86400000)>7;return `<section class="card"><div class="card-body"><div class="model-bar"><strong>选股模型</strong><select id="selection-model" aria-label="选择具体模型版本">${option('','请选择可用模型',S.config.model_version)}${available.map(m=>option(m.version_id,`${m.name} · ${m.version_id.slice(0,12)}${m.status!=='available'?'（'+labels[m.status]+'）':''}`,S.config.model_version)).join('')}</select>${m?`<span class="pill blue">固定版本</span><span class="subtle">${esc(m.description||'在冻结评分范围内计算完整分数')}</span>${btn('模型详情','model-info',`data-id="${esc(m.version_id)}"`,'link')}`:''}<span class="model-date">▦ 数据日期 <strong>${esc(date||'暂无可计算日期')}</strong></span></div>${!available.length?notice('暂无前台可用模型。请在研究工作区查看冻结候选，并人工设为可用。','warning'):''}${m&&!ready?notice(m.blocked_reason||'当前绑定版本不可计算，请查看模型状态及数据要求。','warning'):''}${stale?notice(`当前最新完整实际数据日为 ${date}，距今超过 7 天。生成结果将明确使用该历史日期。`,'warning'):''}${S.plan?`<p class="subtle">已加载方案 <strong>${esc(S.plan.name)}</strong> · 修订 ${esc(S.plan.revision)} · 绑定原模型版本</p>`:''}<div class="filter-line" style="margin-top:17px">${filterControl('board','上市板块')}${filterControl('listing_days','上市天数')}${filterControl('amount','日成交额')}${filterControl('turnover','换手率')}<label>入选数量 Top N<input id="top-n" type="number" min="1" max="10000" step="1" value="${esc(S.config.top_n)}"><small>不足 N 时返回实际数量</small></label></div><div class="row" style="margin-top:18px"><span class="pill">市值 · 未开放</span><span class="pill">行业 · 未开放</span><span class="pill">财务 · 未通过时点核验</span>${btn('清空附加条件','clear-filters','','link')}</div><div class="filter-bottom"><div class="subtle">ⓘ 条件间为 AND（同时满足）；自定义条件尚无对应历史评价。</div><div class="actions">${btn('生成选股结果','generate-selection','','primary',!ready||!!S.selectionJob)}${btn(S.plan?'保存新修订':'保存为方案','save-plan','', '',!m)}</div></div></div></section><div id="selection-job">${selectionJobView()}</div><div id="selection-result">${S.result?resultView(S.result):`<section class="card">${empty('开始你的第一次选股','选择可用模型，设置有数据支持的条件，生成名单。成功结果自动保存到选股记录。')}</section>`}</div><div class="footnote">评分顺序：模型完整评分范围 → 基础资格 → 用户过滤 → Top N。过滤不改变模型权重，也不重新标准化。</div>`;}
function selectionJobView(){const j=S.selectionJob||S.lastSelectionJob;if(!j)return '';return `<div class="notice ${['failed','interrupted'].includes(j.status)?'error':''}" style="margin-bottom:20px"><div class="row">${badge(j.status)}<span>选股任务 ${esc(j.id?.slice(0,12))}</span>${j.status==='running'||j.status==='queued'?'<span>计算期间可继续查看上一份成功结果。</span>':''}</div>${j.error?`<div>${esc(j.error)}</div>`:''}${j.config?`<span class="subtle">已固定提交：${esc(j.config.model_version)} · Top ${esc(j.config.top_n)}</span>`:''}</div>`;}
function resultView(r){const rows=r.rows||[],c=r.counts||{},extra=['board','listing_days','amount','turnover'].filter(k=>rows.some(x=>x[k]!=null)),names={board:'上市板块',listing_days:'上市天数',amount:'日成交额',turnover:'换手率'};return `<section class="card"><div class="card-head"><div class="row"><h3>本次选股</h3><span class="subtle">已入选 ${rows.length} 只 · ${esc(r.data_date||'—')}</span></div><div class="actions">${btn('保存本次配置','save-result-plan',`data-id="${esc(r.id)}"`,'link')}<a href="/api/results/${enc(r.id)}/csv" download>↥ 导出完整名单</a></div></div><div class="result-meta"><span>模型 ${esc(r.model_name||r.model_version)}</span><span>版本 ${esc(r.model_version)}</span><span>数据 ${esc(r.dataset_id)}</span></div><div class="card-body"><div class="metric-row">${metric('模型评分范围',c.scoring_universe)}${metric('基础资格',c.basic_eligible)}${metric('有效评分覆盖',c.coverage)}${metric('用户过滤后',c.after_filter)}${metric('最终入选',c.selected??rows.length)}</div>${json('本次固定输入与条件',r.config)}</div>${rows.length?table(['排名','股票代码','股票名称','综合得分 ↓',...extra.map(k=>esc(names[k])),'操作'],rows.map((r,i)=>td([`<span class="rank">${esc(r.rank??i+1)}</span>`,`<span class="mono">${esc(r.code)}</span>`,`${btn(esc(r.name||'—'),'stock-detail',`data-index="${i}"`,'link stock-name')}`,`<span class="score">${num(r.score,6)}</span>`,...extra.map(k=>k==='board'?esc(r[k]||'—'):num(r[k],4)),btn('查看解释','stock-detail',`data-result="${esc(S.result?.id===r.id?r.id:'')}" data-index="${i}"`,'link')]))):empty('没有股票符合本次条件','已按固定条件计算，未自动放宽限制。请查看本次输入与各阶段计数。')}<div class="card-body subtle">${esc(r.evaluation_note||'该选股配置尚无独立历史评价。模型原始验证不代表本次过滤条件的历史表现。')}<br>结果 ${esc(r.id)} · 保存于 ${when(r.created_at)}</div></section>`;}
function planAvailability(plan,model){
 if(!model||model.status!=='available')return badge(model?.status||'版本不可用');
 if(!model.data_ready)return badge('数据未就绪');
 const dataset=S.datasets.find(d=>d.id===model.dataset_id);
 const blocked=Object.keys(plan.config.filters||{}).filter(k=>dataset?.filters?.[k]?.enabled!==true);
 return blocked.length?'<span class="pill amber">条件当前不可用</span><br><span class="subtle">加载后查看原因并明确调整</span>':badge('available');
}
function planView(){return `<div class="page-intro"><div><div class="eyebrow">SAVED PLANS</div><h2>保存配置，下次继续</h2><div class="subtle">每套方案锁定具体模型版本；条件修改保存为新修订，原记录始终保留。</div></div>${btn('新建方案','navigate','data-page="selection"','primary')}</div><section class="card">${S.plans.length?table(['方案名称','修订','绑定模型版本','数量','当前状态','操作'],S.plans.map(p=>{const m=S.models.find(m=>m.version_id===p.config.model_version);return td([esc(p.name),esc(p.revision),`<span class="mono">${esc(p.config.model_version)}</span>`,esc(p.config.top_n),planAvailability(p,m),btn('加载到工作台','load-plan',`data-id="${esc(p.id)}"`,'link')])})):empty('尚未保存方案','在选股工作台保存模型版本、附加条件与数量。方案不固定股票名单。')}</section>`;}
function historyView(){return `<div class="page-intro"><div><div class="eyebrow">SELECTION HISTORY</div><h2>每次结果，都可追溯</h2><div class="subtle">历史配置、实际数据日期与模型版本保持不变。</div></div></div><div class="toolbar"><input class="search" id="history-search" value="${esc(S.historyQuery||'')}" placeholder="搜索模型、日期或结果编号" aria-label="搜索历史结果"><span class="subtle">${S.results.length} 条成功结果</span></div><section class="card" id="history-table">${historyTable(S.results)}</section><div id="history-result"></div>`;}
function historyTable(rows){const size=S.pageSize||50,query=(S.historyQuery||'').toLowerCase();rows=rows.filter(r=>[r.id,r.model_name,r.model_version,r.data_date].some(x=>String(x||'').toLowerCase().includes(query)));const total=rows.length,pagesCount=Math.max(1,Math.ceil(total/size));S.historyPage=Math.min(S.historyPage||0,pagesCount-1);const pageRows=rows.slice(S.historyPage*size,(S.historyPage+1)*size);return rows.length?table(['实际数据日','模型','结果编号','入选数','创建时间','操作'],pageRows.map(r=>td([esc(r.data_date),esc(r.model_name||r.model_version),`<span class="mono">${esc(r.id)}</span>`,esc(r.counts?.selected??r.rows?.length??'—'),when(r.created_at),btn('查看结果','history-result',`data-id="${esc(r.id)}"`,'link')])))+`<div class="card-body row between"><span class="subtle">第 ${S.historyPage+1} / ${pagesCount} 页 · ${total} 条结果</span><div class="actions">${btn('上一页','history-page','data-delta="-1"','',S.historyPage===0)}${btn('下一页','history-page','data-delta="1"','',S.historyPage>=pagesCount-1)}</div></div>`:empty('暂无结果记录','成功计算的选股结果会自动保存于此。');}
function jobsView(){return `<div class="page-intro"><div><div class="eyebrow">TASK MONITOR</div><h2>后台任务</h2><div class="subtle">本地计算串行排队。研究暂停与停止请求在检查点生效。</div></div></div><section class="card">${S.jobs.length?table(['任务','类型','状态','更新','详情'],S.jobs.map(j=>td([`<span class="mono">${esc(j.id?.slice(0,16))}</span>`,esc(labels[j.kind]||j.kind),badge(j.status),when(j.updated_at||j.created_at),`<details><summary>${j.error?'查看错误':'查看任务'}</summary><pre>${esc(pretty(j))}</pre></details>`]))):empty('没有后台任务','启动研究、最终测试或生成选股结果后，可在这里查看状态与错误。')}</section>`;}
function settingsView(){return `<section class="card"><div class="card-head"><h3>本地设置</h3></div><div class="card-body"><form id="settings-form" class="stack"><div class="form-grid"><label>默认工作区<select name="default_workspace">${option('research','研究工作区',S.settings.default_workspace)}${option('selection','选股工作区',S.settings.default_workspace)}</select></label><label>默认每页记录数<select name="page_size">${[20,50,100].map(v=>option(v,String(v),S.settings.page_size)).join('')}</select></label></div><p class="subtle">当前浏览器会记住最近工作区与未提交的选股配置。</p><div><button class="primary" type="submit">保存设置</button></div><div class="error-text" id="settings-error" role="alert"></div></form></div></section>`;}
function helpView(){const items=S.help?.items||[];return `<div class="page-intro"><div><div class="eyebrow">METHOD & GUIDE</div><h2>${esc(S.help?.title||'研究与选股说明')}</h2><div class="subtle">理解数据、研究协议、模型版本与选股结果的关系。</div></div></div><div class="grid">${items.map(item=>`<section class="card"><div class="card-head"><h3>${esc(item.title)}</h3></div><div class="card-body subtle">${esc(item.text)}</div></section>`).join('')}</div><section class="card"><div class="card-head"><h3>操作路径</h3></div><div class="card-body"><div class="stack">${notice('1. 在数据中心导入已登记原始数据，查看实际覆盖日期、字段与质量。')}${notice('2. 建立项目与实验，核对完整协议后启动。运行与迭代页可暂停、恢复和停止。')}${notice('3. 研究完成后在模型管理查看冻结候选证据，人工设为前台可用。')}${notice('4. 切换选股工作区，选择模型和条件，生成结果、查看股票贡献、保存方案或导出。')}</div></div></section>`;}

async function newExperiment(clone=false){if(!S.datasets.length)await lists(['datasets']);if(!S.projects.length)await lists(['projects']);const source=clone?S.experiment:null,ds=source?.dataset_id||S.datasets[0]?.id;if(!ds)throw Error('尚无可用数据快照，请先导入。');protocolDraft=source?structuredClone(source.protocol):await api(`/datasets/${enc(ds)}/protocol`);dialog(clone?'派生新实验':'新建研究实验',`<form id="experiment-form" class="stack"><div class="form-grid"><label>实验名称<input name="name" required maxlength="150" value="${esc(source?source.name+' · 新协议':'')}" placeholder="描述本次研究目标"></label><label>所属项目<select name="project_id" required>${S.projects.map(p=>option(p.id,p.name,source?.project_id||S.project)).join('')}</select></label><label>数据快照<select id="experiment-dataset" name="dataset_id">${S.datasets.map(d=>option(d.id,d.name||d.id,ds)).join('')}</select></label></div>${notice('日期来自数据实际日历。请确认完整协议后创建，启动时将锁定；小预算只验证机制，不代表研究有效。')}<div id="protocol-friendly">${friendlyProtocol(protocolDraft)}</div><details class="research-advanced"><summary>高级编辑 · 完整协议 JSON</summary><label>完整协议（参数面板已同步常用项）<textarea id="protocol-json" class="protocol-editor" rows="17" spellcheck="false">${esc(pretty(protocolDraft))}</textarea></label><div class="row">${btn('从 JSON 更新参数面板','sync-protocol','','link')}<span class="subtle">参数面板变更会同步更新 JSON；提交以 JSON 为准。</span></div></details><div class="dialog-foot">${btn('取消','close-dialog')}<button class="primary" type="submit">创建实验草稿</button></div></form>`);}
function friendlyProtocol(p){const keys=[['seed','随机种子（复现抽样）'],['top_k','每期目标持股数'],['max_factors','组合因子容量上限'],['batches','批次数'],['episodes_per_batch','每批候选'],['search_budget','组合搜索预算'],['max_backtests','最大回测次数'],['buy_fee','买入费率'],['sell_fee','卖出费率'],['risk_lambda','风险 λ'],['beta','复杂度 β'],['tau','奖励尺度 τ'],['delta','接受阈值 δ']];return `<div class="form-grid">${keys.map(([k,l])=>`<label>${l}<input type="number" step="any" data-protocol="${k}" value="${esc(p[k])}"></label>`).join('')}<label>生成器<select data-protocol="generator">${['ppo','random','fixed'].map(v=>option(v,{ppo:'PPO · 策略学习',random:'随机生成',fixed:'固定因子'}[v],p.generator)).join('')}</select></label><label>奖励目标<select data-protocol="reward_mode">${['trade_delta','single_ic','combo_ic','absolute_trade'].map(v=>option(v,{trade_delta:'交易增量',single_ic:'单因子 IC',combo_ic:'组合 IC',absolute_trade:'绝对交易表现'}[v],p.reward_mode)).join('')}</select></label>${Object.entries(p.segments||{}).map(([k,v])=>`<label>${{F:'F · 组合搜索期',E:'E · 候选反馈期',V:'V · 模型选择期',T:'T · 冻结后测试期'}[k]||esc(k)} · 开始<input type="date" data-segment="${esc(k)}" data-edge="0" value="${esc(v[0])}"></label><label>${{F:'F · 组合搜索期',E:'E · 候选反馈期',V:'V · 模型选择期',T:'T · 冻结后测试期'}[k]||esc(k)} · 结束<input type="date" data-segment="${esc(k)}" data-edge="1" value="${esc(v[1])}"></label>`).join('')}</div>`;}
function evaluationLabel(status){return status==='completed'?'已完成评价':labels[status]||status||'查看证据';}
function modelEvaluationSummary(m){const e=m.evaluation&&typeof m.evaluation==='object'?m.evaluation:{},prototype=e.synthetic||e.data_mode==='legacy_prototype'||m.data_mode==='legacy_prototype',observed=e.holdout_status==='previously_observed_historical'||e.test?.holdout_status==='previously_observed_historical';const pct=value=>value==null?'—':num(Number(value)*100,2)+'%';return `<div style="margin:18px 0"><div class="row between" style="margin-bottom:12px"><strong>模型评价摘要</strong><span class="pill">${esc(evaluationLabel(e.status))}</span></div>${prototype?notice('原型研究诊断：以下为登记协议下的历史评价，不表示模型效果已经验证。','warning'):''}${observed?`<p class="subtle">历史数据已被观察；T 结果不属于全新未观察的留出验证。</p>`:''}${table(['分区 / 用途','实际评价区间','总收益','最大回撤','手续费合计','滑点成本'],[['V · 模型选择',e.selection],['T · 最终测试',e.test]].map(([title,value])=>{const metrics=value?.metrics||{},bounds=value?.bounds;return td([title,value?esc(bounds?.length===2?bounds.join(' 至 '):'区间未提供'):'未运行',pct(metrics.total_return),pct(metrics.max_drawdown),num(metrics.total_fees,2),num(metrics.total_slippage,2)]);} ))}<p class="subtle">收益与成本沿用原始研究协议，仅对应上表区间，不代表用户附加过滤条件的历史表现。</p></div>`;}
async function openModel(id,readonly=false){const m=await api(`/models/${enc(id)}`);dialog(readonly?'模型详情':'模型版本管理',`<div class="row between"><div><h3>${esc(m.name)}</h3><span class="subtle">${Object.keys(activePool(m.weights||{})).length} 个评分因子 · 数据截至 ${esc(m.data_date||'未记录')}</span></div><div class="row">${badge(m.status)}${m.is_default?'<span class="pill blue">本组默认版本</span>':''}</div></div><p class="subtle">${esc(m.description||'尚未填写说明')}</p>${m.blocked_reason?notice(m.blocked_reason,'warning'):''}<div class="research-key-values"><div><span>评分股票范围</span><strong>${esc(m.universe_count)} 只</strong></div><div><span>默认目标持股</span><strong>${esc(m.default_top_k)} 只</strong></div><div><span>输入数据是否就绪</span><strong>${m.data_ready?'已就绪':'未就绪'}</strong></div></div><details><summary>查看实际 ${Object.keys(activePool(m.weights||{})).length} 个评分因子与权重</summary>${factorWeightsTable(m.weights||{})}</details>${json('高级原始证据 · 版本、字段与计算要求',{version_id:m.version_id,required_fields:m.required_fields,source:m.source})}${modelEvaluationSummary(m)}${json('研究来源与评价证据',{source:m.source,source_experiment_id:m.source_experiment_id,source_dataset_id:m.source_dataset_id,evaluation:m.evaluation})}${m.source_experiment_id?btn('查看来源实验 →','model-source',`data-id="${esc(m.source_experiment_id)}"`,'link'):''}${readonly?'':`<form id="model-form" data-id="${esc(id)}" class="stack" style="margin-top:20px"><label>模型名称<input name="name" required value="${esc(m.name)}"></label><label>归属模型（计算版本和已保存方案保持不变）<select name="model_id">${S.models.filter((x,i,a)=>a.findIndex(y=>y.model_id===x.model_id)===i).map(x=>option(x.model_id,x.name,m.model_id)).join('')}</select></label><label>模型说明<textarea name="description" rows="3">${esc(m.description||'')}</textarea></label><div class="form-grid"><label>研究者<input name="researcher" value="${esc(m.researcher||'')}"></label><label>标签（逗号分隔）<input name="tags" value="${esc((m.tags||[]).join(', '))}"></label></div><div class="actions"><button type="submit" class="primary">保存展示信息</button>${btn('设为前台可用','model-status',`data-id="${esc(id)}" data-status="available"`,'',m.status==='available')}${btn('停用版本','model-status',`data-id="${esc(id)}" data-status="disabled"`,'danger',m.status==='disabled')}${btn('设为本组默认版本','default-model',`data-id="${esc(id)}"`,'',m.is_default)}</div></form>`}`);}
function fieldCatalogTable(fields,query=''){
 const needle=query.trim().toLowerCase(),rows=fields.filter(f=>[f.name,f.description,f.source_notes].some(v=>String(v||'').toLowerCase().includes(needle)));
 const roles={financial_quarantine:'财务隔离',security_attribute_unverified_history:'证券属性 · 历史待核验',market_observation:'行情观测',source_only:'仅源字段目录'};
 return `<p class="subtle">显示 ${rows.length} / ${fields.length} 个字段</p>`+(rows.length?table(['字段名','中文说明','文档备注','用途 / 可用性','来源与元数据'],rows.map(f=>td([
  `<span class="mono">${esc(f.name)}</span>`,esc(f.description||'未提供说明'),esc(f.source_notes||'—'),
  `${esc(roles[f.role]||f.role||'查看元数据')}<br><span class="subtle">${f.imported?'已导入值':'未导入值'} · ${f.training_allowed?'原型信号白名单':'未开放训练'}</span>`,
  `${f.documentation?`<span class="subtle">${esc(f.documentation.file)} · 第 ${esc(f.documentation.line)} 行</span>`:'<span class="pill">文档未收录</span>'}${json('查看元数据',f)}`
 ]))):empty('没有匹配字段','可搜索字段名、中文说明或文档备注。'));
}
